WITH lines AS (SELECT id, currency, EXPLODE(tier_prices) AS tier_value FROM price_tiers) SELECT *, CUME_DIST() OVER (ORDER BY tier_value DESC NULLS LAST) AS tier_value_cume_dist, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value) AS tier_value_dense_rank, SUM(tier_value) OVER w_hist AS currency_sum_tier_value, STDDEV_SAMP(tier_value) OVER w_hist AS currency_stddev_samp_tier_value FROM lines WINDOW w_hist AS (PARTITION BY currency)
